import fs from 'node:fs';
import path from 'node:path';
import { planTracking, applyTracking } from './scripts/lib/stage-tracking-migration.mjs';
import { parseYaml, binding, assertStageTracking } from './scripts/lib/stage-tracking.mjs';
import { stringify } from './scripts/vendor/yaml.mjs';
const root=process.cwd();
function put(ref,value){const file=path.join(root,ref);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,typeof value==='string'?value:stringify(value));}
put('yss-project.yaml',{schema_version:1,repository_mode:'project-instance'});
// Retain the source CONTEXT contract. This replaces only the synthetic tracker config.
put('.template-spec/agents/issue-tracker.md','---\ntracker:\n  platform: local-markdown\n  lifecycle_tracking_version: 1\n---\n# Synthetic evaluation tracker\n');
const checkpointRef='docs/.scratch/skills-eval/checkpoint.yaml';
put('docs/.scratch/skills-eval/plan/input.md','测试数据：库存导入重复项拒绝覆盖，保留原有库存。\n');
const item={id:'scope',title:'明确导入覆盖规则',stage:'stage.plan',work_unit:'work-unit.plan-requirements',owner:'fixture-owner',scope:'明确重复数据如何处理',acceptance:['重复项拒绝覆盖并保留原库存'],source_refs:['docs/.scratch/skills-eval/plan/input.md']};
const plan=planTracking(root,{checkpoint_ref:checkpointRef,items:[item]});applyTracking(root,plan);
const checkpoint=parseYaml(fs.readFileSync(path.join(root,checkpointRef),'utf8'));
put('docs/.scratch/skills-eval/verification/scope.md','测试数据验收：输入库存5，导入重复记录10，预期拒绝覆盖且保留5。\n');
const tracked=checkpoint.stage_tracking.items[0];tracked.progress='completed';tracked.completion=tracked.acceptance.map(criterion=>({criterion,evidence_refs:[binding(root,'docs/.scratch/skills-eval/verification/scope.md')]}));
checkpoint.stage='stage.plan';checkpoint.mode='resume';checkpoint.status='paused';checkpoint.phase_boundary={decision:'pause',reason:'Plan 阶段仍待真实用户审阅批准；工作项完成不等于门禁批准'};
checkpoint.human_review.required=true;checkpoint.human_review.status='pending';checkpoint.next_work_unit='work-unit.spec-synthesis';
put(checkpointRef,checkpoint);
const result=assertStageTracking(checkpoint,{root});if(result.status!=='valid')throw new Error('invalid prepared tracking');
put('.eval-input/lifecycle-preparation.json',{test_data_only:true,tracking_status:result.status,plan_approval:'pending',checkpoint:checkpointRef});
